H.background();
const I = P.cur, A = P.area, n = P.dens;
const wireY = H.H * 0.52, wireX0 = 40, wireX1 = H.W - 40;
const wireLen = wireX1 - wireX0;
H.text("Electric current:  I = Q / t", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
// wire thickness encodes the cross-section A (mm^2)
const thick = H.clamp(28 + A * 12, 28, 80);
H.rect(wireX0, wireY - thick / 2, wireLen, thick, { fill: H.colors.panel, stroke: H.colors.grid, width: 2, radius: 8 });
const planeX = wireX0 + wireLen * 0.5;
H.line(planeX, wireY - thick / 2 - 10, planeX, wireY + thick / 2 + 10, { color: H.colors.warn, width: 2, dash: [5, 5] });
H.text("cross-section A", planeX - 44, wireY - thick / 2 - 16, { color: H.colors.warn, size: 12 });
const q = 1.6e-19;
// drift velocity v_d = I / (n A q): more current -> faster, but more carriers
// or a fatter wire -> slower drift for the SAME current. (rel. units for n,A)
const vdrift = I / (n * A);
const speed = H.clamp(30 + vdrift * 90, 18, 220);
// number of carriers shown scales with carrier density n
const N = Math.round(H.clamp(6 + n * 4, 6, 26));
const rows = 3;
for (let i = 0; i < N; i++) {
  const phase = (i / N);
  let xp = ((t * speed / wireLen + phase) % 1);
  const ex = wireX0 + xp * wireLen;
  const ey = wireY - (thick / 2 - 8) + (i % rows) * ((thick - 16) / (rows - 1));
  H.circle(ex, ey, 5, { fill: H.colors.accent, stroke: H.colors.bg, width: 1 });
  H.text("-", ex - 2.5, ey + 3.5, { color: H.colors.bg, size: 10, weight: 700 });
}
H.arrow(wireX0 + 30, wireY - thick / 2 - 24, wireX0 + 130, wireY - thick / 2 - 24, { color: H.colors.accent2, width: 3 });
H.text("conventional current  I", wireX0 + 30, wireY - thick / 2 - 30, { color: H.colors.accent2, size: 12 });
const Q = I * t;
H.text("I = " + I.toFixed(2) + " A    charge passed  Q = I·t = " + Q.toFixed(1) + " C  (after " + t.toFixed(1) + " s)", 24, 54, { color: H.colors.sub, size: 13 });
H.text("A = " + A.toFixed(1) + " mm²   carrier density n = " + n.toFixed(1) + " (rel.)   drift v ∝ I/(nA) = " + vdrift.toFixed(2), 24, 76, { color: H.colors.sub, size: 12 });
H.text("electrons per second through plane ~ " + (I / q).toExponential(2), 24, H.H - 24, { color: H.colors.good, size: 12 });
H.legend([{ label: "electron drift", color: H.colors.accent }, { label: "current I", color: H.colors.accent2 }], H.W - 180, 30);
